const LEGAL_BASE_URL = 'https://www.shakersworks.com';
const LEGAL_PREFIXES = { es: '', en: 'en/', pt: 'pt/', it: 'it/' };

function termsLinks(lang) {
  const code = String(lang || 'en').toLowerCase().split('-')[0];
  const prefix = code in LEGAL_PREFIXES ? LEGAL_PREFIXES[code] : 'en/';
  return { terms: `${LEGAL_BASE_URL}/${prefix}condiciones-generales`, privacy: `${LEGAL_BASE_URL}/${prefix}politica-de-privacidad` };
}

function termsText(lang, link) {
  const code = String(lang || 'en').toLowerCase().split('-')[0];
  const legal = LEGAL[code] || LEGAL.en;
  const links = termsLinks(code);
  return legal.terms((label) => link(label, links.terms), (label) => link(label, links.privacy));
}

const LOCALES = { es: 'es-ES', en: 'en-GB', it: 'it-IT', pt: 'pt-PT' };

// "a, b and c" in the talent's language.
function listOf(lang, items) {
  return new Intl.ListFormat(LOCALES[lang], { type: 'conjunction' }).format(items);
}

// The names of only the sources the talent actually gave (cv, linkedin), from a per-language table.
function named(sources, names) {
  return (sources || []).map((s) => names[s]).filter(Boolean);
}

function joinParts(parts) {
  return parts.filter((p) => p !== null && p !== undefined && String(p).trim() !== '').join(' · ');
}

function countryName(lang, code) {
  if (typeof code !== 'string' || !/^[A-Za-z]{2}$/.test(code.trim())) return null;
  const upper = code.trim().toUpperCase();
  try {
    return new Intl.DisplayNames([LOCALES[toSignupLanguage(lang) || 'en']], { type: 'region' }).of(upper) || upper;
  } catch {
    return upper;
  }
}

function amount(lang, value) {
  return new Intl.NumberFormat(LOCALES[lang], { maximumFractionDigits: 0 }).format(Number(value));
}

