function signupCopy(lang) {
  return COPY[toSignupLanguage(lang) || 'en'];
}

function trustCopy(lang) {
  return TRUST[toSignupLanguage(lang) || 'en'];
}

function legalCopy(lang) {
  return LEGAL[toSignupLanguage(lang) || 'en'];
}

function reviewCopy(lang) {
  return REVIEW[toSignupLanguage(lang) || 'en'];
}

function applyCopy(lang) {
  return APPLY[toSignupLanguage(lang) || 'en'];
}

function detectedAgentsCopy(lang) {
  return DETECTED_AGENTS[toSignupLanguage(lang) || 'en'];
}

// The profile draft the talent confirms before the account exists, with every field the account is created with: one line per group, empty parts left out.
function renderDraft(lang, d = {}) {
  const c = signupCopy(lang);
  const has = (v) => v !== null && v !== undefined && String(v).trim() !== '';
  const place = [d.city, countryName(lang, d.country)].filter(has).join(', ');
  const situation = c.situationLabels[d.situation];
  const participation = d.situation === 'EMPLOYED' ? c.participationLabels[d.participation] : null;
  const lines = [
    joinParts([d.name, d.role, place]),
    situation ? `${c.keptLabels.workSituation}: ${participation ? `${situation} (${participation})` : situation}` : '',
    joinParts([has(d.yearsOfExperience) ? c.years(d.yearsOfExperience) : null, d.stack]),
    joinParts([d.languages, d.workMode, has(d.monthlyHours) ? c.hours(d.monthlyHours) : null]),
    has(d.hourlyRate) || has(d.annualRate) ? c.rates(has(d.hourlyRate) ? d.hourlyRate : null, has(d.annualRate) ? d.annualRate : null, d.ratesFromTalent !== true) : '',
    has(d.email) ? `${c.emailLabel}: ${d.email}` : '',
  ].filter(Boolean);
  return [c.draftTitle, ...lines].join('\n');
}

// One role of the main-role step: name, why it fits (source + one fact) and, when known, how many open projects want it.
function renderRole(lang, { name, source, evidence, openProjects, recommended }) {
  const c = signupCopy(lang);
  const reason = c.roleReason[source] || null;
  const why = reason && evidence ? `${reason}: ${evidence}` : reason || evidence || null;
  return [
    recommended ? c.roleRecommended(name) : c.roleName(name),
    why,
    typeof openProjects === 'number' && openProjects > 0 ? c.openProjects(openProjects) : null,
  ].filter(Boolean).join('\n');
}

module.exports = { SIGNUP_LANGUAGES, LEGAL, REVIEW, signupCopy, legalCopy, trustCopy, termsText, reviewCopy, detectedAgentsCopy, applyCopy, toSignupLanguage, renderDraft, renderRole, amount };
